; DDATA.S - SHARED DATA AND TABLES

CURRPAGE:
    .BYTE 0
NEEDREDRAW:
    .BYTE 0

PAGEROUTINETABLE:
    .WORD DSYSRENDER
    .WORD DAPPRENDER
    .WORD DVMMRENDER
; PAGEROUTINETABLE_END - ZERO-BYTE LOCATION MARKER. DASH_WRAPPER.S ASSERTS
; (PAGEROUTINETABLE_END - PAGEROUTINETABLE) / 2 == PAGECOUNT (CA65-ONLY).
PAGEROUTINETABLE_END:

; DASHVERSTR - STATIC VERSION/BUILD STRING, PRINTED ON SCREEN ROW 24 BY
; DRAWFRAME'S DRAWVERSIONBANNER (DSCR.S) -- SO IT APPEARS ON EVERY PAGE
; (SYSTEM, APPLICATIONS, VMM TEST), NOT JUST THE SYSTEM PAGE. HAND-BUMPED,
; SAME "APPNAME V<MAJOR>.<MINOR>.<BUILD>" SHAPE AS
; OTHER EXTERNAL APPS' VERSION BANNERS (E.G. CASM.S'S "CASM V0.1.50.<BUILD>",
; SOURCED THERE FROM A CA65 .DEFINE + GENERATED BUILD_CASM.INC). DASH CANNOT
; USE THAT MECHANISM: THE DUAL-ASSEMBLER SUBSET HAS NO EQUATES, SO NATIVE
; CASM CAN'T CONSUME A GENERATED BUILD_DASH.INC THE SAME WAY. A FULLY STATIC
; STRING ALSO KEEPS THIS IMMUNE TO THE PRINTDEC16 SPACING BUG IT EXISTS TO
; HELP DIAGNOSE, SINCE IT NEVER CALLS FORMATDEC16/PRINTDEC16 AT ALL.
DASHVERSTR:
    .BYTE $04, $01, $13, $08, $20, $16, "0.1.4", $00

; FMTBUF - SHARED 5-BYTE APPLICATION-RAM FORMATTING BUFFER.
; USED BY FORMATHEX8 (3 OF 5 BYTES), FORMATHEX16 (ALL 5), AND FORMATDEC16
; (ALL 5, FIXED-WIDTH, NO TERMINATOR). NOT REENTRANT ACROSS FORMAT CALLS.
FMTBUF:
    .RES 5

; HEXDIGITS - SCREEN-CODE DIGITS FOR VALUES 0-15: '0'-'9' THEN 'A'-'F'.
HEXDIGITS:
    .BYTE "0123456789", $01, $02, $03, $04, $05, $06

; TABCOLSTART/TABCOLLEN - TAB ROW (ROW 2) LABEL COLUMN RANGES, ONE ENTRY PER
; PAGE (SYSTEM, APPLICATIONS, VMM TEST), USED BY HIGHLIGHTTABS.
TABCOLSTART:
    .BYTE 2, 11, 26
TABCOLLEN:
    .BYTE 6, 12, 8

BORDERROW:
    .BYTE $5B
    .RES 38, $40
    .BYTE $5B

TITLEROW:
    .BYTE $5D, $20, $03, $0F, $0D, $0D, $01, $0E, $04, $20
    .BYTE $36, $34, $20, $13, $19, $13, $14, $05, $0D, $20
    .BYTE $04, $01, $13, $08, $02, $0F, $01, $12, $04, $20
    .BYTE "         ", $5D

TABSROW:
    .BYTE $5D, $20, $13, $19, $13, $14, $05, $0D, $20, $20
    .BYTE $20, $01, $10, $10, $0C, $09, $03, $01, $14, $09
    .BYTE $0F, $0E, $13, $20, $20, $20, $16, $0D, $0D, $20
    .BYTE $14, $05, $13, $14, "     ", $5D

STATUSROW:
    .BYTE $5D, $20, $06, $31, $2F, $06, $33, $2F, $06, $35
    .BYTE $20, $10, $01, $07, $05, $20, $20, $12, $20, $12
    .BYTE $05, $06, $12, $05, $13, $08, $20, $20, $11, $20
    .BYTE $11, $15, $09, $14, "     ", $5D

SYSTITLESTR:
    .BYTE $13, $19, $13, $14, $05, $0D, $20, $10, $01, $07, $05, $00

; SYSINFOBUF - 24-BYTE DOS_GET_SYSTEM_INFO ($5C) RECORD, FILLED BY
; QUERYSYSTEMINFO (DSYS.S) ONCE PER SYSTEM-PAGE REDRAW. SEE DSYS.S FOR THE
; OFFSET MAP (MIRRORS SYS_INFO_OFF_* IN INCLUDE/COMMAND64.INC, WHICH CASM
; CANNOT .INCLUDE -- NO EQUATES IN THE DUAL-ASSEMBLER SUBSET).
SYSINFOBUF:
    .RES 24

SYSFAILSTR:
