; APPBUF - 24-BYTE DOS_GET_APP_INFO ($5D) RECORD, FILLED BY DAPPRENDER (DAPP.S)
; ONCE PER SLOT PER APPLICATIONS-PAGE REDRAW. OFFSETS PER THE WP1 APP RECORD:
; 0 STRUCTVERSION, 1 STRUCTSIZE, 2 SLOTINDEX, 3 FLAGS, 4/5 LOADADDR LO/HI,
; 6/7 SIZE LO/HI, 8 NAMELEN, 9-23 NAMEDATA (15 RAW PETSCII BYTES).
APPBUF:
    .RES 24

; APPENDLO/APPENDHI - SCRATCH FOR DAPP.S'S CARRY-AWARE INCLUSIVE-END
; COMPUTATION (LOADADDR + SIZE - 1). APPLICATION RAM, NOT ZERO PAGE, SINCE
; THE $70-$8F RANGE IS ALREADY FULLY ALLOCATED (SEE AGENTS.MD).
APPENDLO:
    .BYTE 0
APPENDHI:
    .BYTE 0

; APPCURSLOT/APPOCCCOUNT - DAPPRENDER'S SLOT LOOP INDEX (0-15) AND OCCUPIED-
; SLOT COUNTER FOR THE "NO APPLICATIONS" CASE.
APPCURSLOT:
    .BYTE 0
APPOCCCOUNT:
    .BYTE 0

APPHDR_NAME:
    .BYTE $0E, $01, $0D, $05, $00

APPHDR_RANGE:
    .BYTE $12, $01, $0E, $07, $05, $00

APPHDR_SIZE:
    .BYTE $13, $09, $1A, $05, $00

APPHDR_FLAGS:
    .BYTE $06, $0C, $01, $07, $13, $00

APPNOAPPSSTR:
    .BYTE $0E, $0F, $20, $01, $10, $10, $0C, $09, $03, $01
    .BYTE $14, $09, $0F, $0E, $13, $00

APPERRSTR:
    .BYTE $01, $10, $10, $20, $11, $15, $05, $12, $19, $20
    .BYTE $05, $12, $12, $0F, $12, $00

APPRANGEBADSTR:
    .BYTE "????", $00

VMMTITLESTR:
    .BYTE $16, $0D, $0D, $20, $14, $05, $13, $14, $20, $10, $01, $07, $05, $00

; VMM TEST PAGE STATE (APPLICATION RAM, NOT ZERO PAGE -- $70-$8F IS FULLY
; ALLOCATED PER AGENTS.MD). PERSISTS ACROSS REDRAWS/PAGE SWITCHES FOR THE
; LIFE OF THE DASH SESSION.
;
; VMMPAGESTATE: 0 UNAVAILABLE, 1 READY, 2 RUNNING, 3 PASSED, 4 FAILED,
;               5 CLEANUP FAILED.
VMMPAGESTATE:
    .BYTE 0
; VMMOWNED - NONZERO WHILE DOS_ALLOC_MEM HAS SUCCEEDED AND NO DOS_FREE_MEM
; HAS YET SUCCEEDED FOR IT. SAVED IMMEDIATELY AFTER A SUCCESSFUL ALLOCATION,
; NEVER TRUSTED FROM OS PARAMETER ZERO PAGE ACROSS SUBSEQUENT CALLS.
VMMOWNED:
    .BYTE 0
; VMMSEGHI/VMMBANKID - THE 2-BYTE ALLOCATION IDENTITY RETURNED IN X/Y BY
; DOS_ALLOC_MEM. VMMSEGLO ($68) IS ALWAYS WRITTEN AS A LITERAL 0 BEFORE EVERY
; TRANSFER -- VMMALLOC ALWAYS RETURNS IT AS 0, SO IT IS NEVER STORED HERE.
VMMSEGHI:
    .BYTE 0
VMMBANKID:
    .BYTE 0
; VMMPATTERNIDX - WHICH OF THE 3 PATTERNS IS CURRENTLY (OR WAS LAST) BEING
; TESTED: 0 = $00/$FF, 1 = $55/$AA, 2 = INCREMENTING.
VMMPATTERNIDX:
    .BYTE 0
; VMMFAILSTAGE - 0 ALLOC, 1 WRITE, 2 READ, 3 COMPARE, 4 FREE, 5 INTERNAL.
; MEANINGFUL ONLY WHEN VMMPAGESTATE IS 4 (FAILED) OR 5 (CLEANUP FAILED).
VMMFAILSTAGE:
    .BYTE 0
; VMMFAILOFFHI/LO - 16-BIT FAILING OFFSET (BLOCKINDEX:LOCALINDEX) FOR A
; COMPARE-STAGE FAILURE. MEANINGLESS FOR OTHER FAIL STAGES.
VMMFAILOFFHI:
    .BYTE 0
VMMFAILOFFLO:
    .BYTE 0
; VMMFAILEXPECT/VMMFAILACTUAL - THE MISMATCHED BYTES FOR A COMPARE-STAGE
; FAILURE.
VMMFAILEXPECT:
    .BYTE 0
VMMFAILACTUAL:
    .BYTE 0
; VMMBLOCKIDX - THE TEST LOOP'S CURRENT BLOCK INDEX (0-15), ALSO DOUBLES AS
; VMMOFFHI SINCE EVERY BLOCK IS 256-BYTE ALIGNED.
VMMBLOCKIDX:
    .BYTE 0

